#!/usr/bin/env bash
set -euo pipefail
WORKSPACE="/home/kavia/workspace/code-generation/uttar-pradesh-tourism-infrastructure-management-system-220373-220382/spring_backend"
cd "$WORKSPACE"
TEST_PATH="src/test/java/com/example/demo/BasicUnitTest.java"
# idempotent create: if file exists, skip writing
if [ ! -f "$TEST_PATH" ]; then
  mkdir -p "$(dirname "$TEST_PATH")"
  # use tee to write file (avoids reliance on external writer helpers)
  sudo tee "$TEST_PATH" > /dev/null <<'TEST'
package com.example.demo;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertTrue;
class BasicUnitTest { @Test void sanity(){ assertTrue(1==1); } }
TEST
  chmod u+rw "$TEST_PATH"
fi
M2_DIR="$WORKSPACE/.m2"; mkdir -p "$M2_DIR"
command -v mvn >/dev/null 2>&1 || { echo 'mvn missing' >&2; exit 30; }
# run tests with limited parallelism and workspace-local repo
mvn -B -T1 -Dmaven.repo.local="$M2_DIR" test || { echo 'mvn test failed' >&2; exit 31; }

